// Unit tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use approx::assert_abs_diff_eq;
    use nalgebra::DVector as DVec;

    fn default_est() -> MusicEstimator {
        MusicEstimator::default()
    }

    // ── hermitian_eigen ───────────────────────────────────────────────────────

    /// Verify faer EVD eigenvalues on a known rank-1 4×4 complex Hermitian matrix.
    /// The rank-1 matrix a·aᴴ has eigenvalues [0, 0, 0, ‖a‖²].
    #[test]
    fn hermitian_eigen_rank1_eigenvalues() {
        let est = default_est();
        let sv = est.steering_vector(PI / 4.0, 500.0); // unit-magnitude elements
        let cov = &sv * sv.adjoint(); // rank-1, ‖sv‖² = 4
        let (mut ev, _) = hermitian_eigen(&cov);
        ev.sort_by(|a, b| a.partial_cmp(b).unwrap());
        // Three near-zero eigenvalues, one equal to ‖sv‖² ≈ 4
        assert_abs_diff_eq!(ev[0], 0.0, epsilon = 1e-8);
        assert_abs_diff_eq!(ev[1], 0.0, epsilon = 1e-8);
        assert_abs_diff_eq!(ev[2], 0.0, epsilon = 1e-8);
        assert_abs_diff_eq!(ev[3], 4.0, epsilon = 1e-8);
    }

    /// MUSIC from a rank-1 covariance built with NOISE: the noise subspace
    /// should be orthogonal to the steering vector, so `estimate_doa` returns the true angle.
    /// This test uses pyMUSIC sign convention: z_i = a(θ)_i × exp(iωt).
    #[test]
    fn estimate_doa_from_rank1_covariance() {
        let est = default_est();
        let true_angle = 0.3_f64; // radians
        let freq = 1000.0_f64;
        let n = est.n_antennas();

        // Build signal aligned with the steering vector (pyMUSIC convention)
        let a = est.steering_vector(true_angle, freq);
        // Covariance = signal subspace + small noise floor
        let cov = &a * a.adjoint() + CMatrix::identity(n, n).scale(0.01_f64);

        let noise = est.noise_subspace(&cov, 1);
        let (scores, angles) = est.spectrum(&noise, freq);
        let peaks = find_peaks(&scores, &angles, 1);
        assert_eq!(peaks.len(), 1);
        let diff = (peaks[0] - true_angle).abs();
        let diff_wrapped = diff.min(2.0 * PI - diff);
        assert!(
            diff_wrapped < 2.0_f64.to_radians(),
            "Expected ~{:.1}°, got {:.1}°",
            true_angle.to_degrees(),
            peaks[0].to_degrees()
        );
    }

    /// Eigenvalues of a diagonal real matrix should be the diagonal entries.
    #[test]
    fn hermitian_eigen_diagonal_real() {
        let mat = CMatrix::from_diagonal(&DVec::from_vec(vec![
            Cplx::new(1.0, 0.0),
            Cplx::new(2.0, 0.0),
            Cplx::new(3.0, 0.0),
        ]));
        let (eigenvalues, _) = hermitian_eigen(&mat);
        let mut ev = eigenvalues.clone();
        ev.sort_by(|a, b| a.partial_cmp(b).unwrap());
        assert_abs_diff_eq!(ev[0], 1.0, epsilon = 1e-10);
        assert_abs_diff_eq!(ev[1], 2.0, epsilon = 1e-10);
        assert_abs_diff_eq!(ev[2], 3.0, epsilon = 1e-10);
    }

    /// Eigenvectors should be unitary: EᴴE ≈ I.
    #[test]
    fn hermitian_eigen_unitary_eigenvectors() {
        let n = 4;
        let est = default_est();
        // Build a rank-1 Hermitian matrix from a steering vector
        let sv = est.steering_vector(0.5, 400.0);
        let cov = &sv * sv.adjoint(); // rank-1
        let (_, vecs) = hermitian_eigen(&cov);
        let g = vecs.adjoint() * &vecs;
        for i in 0..n {
            for j in 0..n {
                let expected = if i == j { 1.0 } else { 0.0 };
                assert_abs_diff_eq!(g[(i, j)].re, expected, epsilon = 1e-9);
                assert_abs_diff_eq!(g[(i, j)].im, 0.0, epsilon = 1e-9);
            }
        }
    }

    // ── steering_vector ───────────────────────────────────────────────────────

    #[test]
    fn steering_vector_length() {
        let est = default_est();
        assert_eq!(est.steering_vector(0.0, 300.0).len(), 4);
    }

    /// All steering-vector elements have unit magnitude.
    #[test]
    fn steering_vector_unit_magnitude() {
        let est = default_est();
        for angle in [0.0, PI / 6.0, PI / 4.0, PI / 2.0, PI, 3.0 * PI / 2.0] {
            for c in est.steering_vector(angle, 500.0).iter() {
                assert_abs_diff_eq!(c.norm(), 1.0, epsilon = 1e-12);
            }
        }
    }

    /// Single element at origin → zero delay → phase = 1+0j for all angles.
    #[test]
    fn steering_vector_origin_element() {
        let est = MusicEstimator::new(vec![[0.0, 0.0]], 360, (0.0, 2.0 * PI), 16000.0);
        let sv = est.steering_vector(1.23, 1000.0);
        assert_abs_diff_eq!(sv[0].re, 1.0, epsilon = 1e-12);
        assert_abs_diff_eq!(sv[0].im, 0.0, epsilon = 1e-12);
    }

    // ── noise_subspace ────────────────────────────────────────────────────────

    /// Identity covariance + 1 source → noise subspace of shape (4 × 3).
    #[test]
    fn noise_subspace_shape() {
        let est = default_est();
        let n = est.n_antennas();
        let cov = CMatrix::identity(n, n);
        let noise = est.noise_subspace(&cov, 1);
        assert_eq!(noise.nrows(), n);
        assert_eq!(noise.ncols(), n - 1);
    }

    /// Noise-subspace columns should be orthonormal: EₙᴴEₙ ≈ I.
    #[test]
    fn noise_subspace_columns_orthonormal() {
        let est = default_est();
        let n = est.n_antennas();
        let cov = CMatrix::identity(n, n);
        let noise = est.noise_subspace(&cov, 1);
        let g = noise.adjoint() * &noise;
        for i in 0..g.nrows() {
            for j in 0..g.ncols() {
                let expected = if i == j { 1.0 } else { 0.0 };
                assert_abs_diff_eq!(g[(i, j)].re, expected, epsilon = 1e-9);
                assert_abs_diff_eq!(g[(i, j)].im, 0.0, epsilon = 1e-9);
            }
        }
    }

    // ── spectrum ──────────────────────────────────────────────────────────────

    /// For a two-element array with identity noise subspace, spectrum is flat.
    #[test]
    fn spectrum_flat_for_full_noise_space() {
        let est = MusicEstimator::new(vec![[0.0, 0.0], [0.1, 0.0]], 360, (0.0, 2.0 * PI), 16000.0);
        let n = est.n_antennas();
        let noise = CMatrix::identity(n, n);
        let (scores, _) = est.spectrum(&noise, 300.0);
        let first = scores[0];
        for &s in &scores[1..] {
            assert_abs_diff_eq!(s, first, epsilon = 1e-9);
        }
    }

    // ── find_peaks ────────────────────────────────────────────────────────────

    #[test]
    fn find_peaks_returns_top_n() {
        let scores = vec![0.1, 1.0, 0.1, 0.1, 2.0, 0.1, 0.1, 3.0, 0.1];
        let angles: Vec<f64> = (0..scores.len()).map(|i| i as f64).collect();
        let peaks = find_peaks(&scores, &angles, 2);
        assert_eq!(peaks.len(), 2);
        assert_abs_diff_eq!(peaks[0], 7.0, epsilon = 1e-12); // highest peak first
    }

    // ── estimate_doa (synthetic noiseless plane wave) ─────────────────────────

    #[test]
    fn estimate_doa_synthetic_source() {
        let est = default_est();
        let true_angle = PI / 4.0; // 45°
        let frequency = 500.0_f64;
        let n_samples = 2048usize;
        let n = est.n_antennas();

        let steering = est.steering_vector(true_angle, frequency);
        let mut data = CMatrix::zeros(n, n_samples);
        for t in 0..n_samples {
            let s = Cplx::from_polar(1.0, 2.0 * PI * frequency * t as f64 / 16000.0);
            for i in 0..n {
                data[(i, t)] = steering[i] * s;
            }
        }

        let angles = est.estimate_doa(&data, 1, frequency);
        assert_eq!(angles.len(), 1);
        let diff = (angles[0] - true_angle).abs();
        let diff_wrapped = diff.min(2.0 * PI - diff);
        assert!(
            diff_wrapped < 3.0_f64.to_radians(),
            "Expected ~{:.1}°, got {:.1}°",
            true_angle.to_degrees(),
            angles[0].to_degrees()
        );
    }
}

//! Short-Time Fourier Transform and analytic signal computation.

use num_complex::Complex;
use rustfft::FftPlanner;

/// Computes the analytic signal of a real-valued input using the Hilbert transform.
///
/// The analytic signal `z(t) = x(t) + j·H{x(t)}` has a one-sided spectrum; its magnitude is the
/// instantaneous envelope and its argument is the instantaneous phase.
///
/// # Algorithm
/// 1. Forward FFT of the real input.
/// 2. Apply the one-sided spectral window H: `H[0] = 1`, `H[1..N/2] = 2`, `H[N/2] = 1` (for
///    even N), `H[N/2+1..] = 0`.
/// 3. Inverse FFT → analytic signal.
///
/// # Examples
/// ```
/// use musicrs::analytic_signal;
/// use std::f64::consts::PI;
/// let n = 256;
/// let cos: Vec<f64> = (0..n).map(|i| (2.0 * PI * 10.0 * i as f64 / n as f64).cos()).collect();
/// let z = analytic_signal(&cos);
/// // Magnitude should be approximately 1 everywhere (after transients settle)
/// for &c in &z[10..n-10] {
///     assert!((c.norm() - 1.0).abs() < 0.01);
/// }
/// ```
pub fn analytic_signal(data: &[f64]) -> Vec<Complex<f64>> {
    let n = data.len();
    let mut planner = FftPlanner::<f64>::new();

    // Forward FFT
    let fft_forward = planner.plan_fft_forward(n);
    let mut spectrum: Vec<Complex<f64>> = data.iter().map(|&x| Complex::new(x, 0.0)).collect();
    fft_forward.process(&mut spectrum);

    // One-sided spectral window
    let half = n / 2;
    spectrum[0] *= 1.0; // DC – unchanged
    for sample in spectrum.iter_mut().take(half).skip(1) {
        *sample *= 2.0;
    }
    // Nyquist bin (index half) is kept unchanged when N is even
    // Negative-frequency bins are zeroed
    for sample in spectrum.iter_mut().take(n).skip(half + 1) {
        *sample = Complex::new(0.0, 0.0);
    }

    // Inverse FFT
    let fft_inverse = planner.plan_fft_inverse(n);
    fft_inverse.process(&mut spectrum);

    // Normalise
    let norm = n as f64;
    spectrum.iter().map(|c| c / norm).collect()
}

/// Computes the Short-Time Fourier Transform of a real-valued signal.
///
/// Returns a matrix of shape `[freq_bins][num_windows]` where
/// `freq_bins = nfft / 2 + 1` (single-sided spectrum via real FFT).
///
/// # Arguments
/// * `data`       – Real-valued input samples.
/// * `nfft`       – Window (FFT) size. Must be ≥ 1.
/// * `no_overlap` – Number of samples shared between consecutive windows.
///
/// # Examples
/// ```
/// use musicrs::stft;
/// use std::f64::consts::PI;
/// let n = 512;
/// let freq_bin = 16usize;
/// let sr = 512.0_f64;
/// let sine: Vec<f64> = (0..n)
///     .map(|i| (2.0 * PI * freq_bin as f64 * i as f64 / sr).sin())
///     .collect();
/// let result = stft(&sine, 64, 0);
/// // Each window should have a peak at `freq_bin` (relative to the window size)
/// assert!(!result.is_empty());
/// ```
pub fn stft(data: &[f64], nfft: usize, no_overlap: usize) -> Vec<Vec<Complex<f64>>> {
    assert!(nfft >= 1, "nfft must be at least 1");
    assert!(no_overlap < nfft, "no_overlap must be less than nfft");

    let step = nfft - no_overlap;
    let freq_bins = nfft / 2 + 1;
    let mut planner = FftPlanner::<f64>::new();
    // Use real-to-complex FFT plan (standard forward FFT on real-padded input)
    let fft = planner.plan_fft_forward(nfft);

    let num_windows = if data.len() >= nfft {
        (data.len() - nfft) / step + 1
    } else {
        0
    };

    // result[freq_bin][window_index]
    let mut result: Vec<Vec<Complex<f64>>> =
        vec![vec![Complex::new(0.0, 0.0); num_windows]; freq_bins];

    for (win_idx, start) in (0..).zip((0..).step_by(step).take(num_windows)) {
        let end = start + nfft;
        let mut buf: Vec<Complex<f64>> = data[start..end]
            .iter()
            .map(|&x| Complex::new(x, 0.0))
            .collect();
        fft.process(&mut buf);
        for bin in 0..freq_bins {
            result[bin][win_idx] = buf[bin];
        }
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use approx::assert_abs_diff_eq;
    use std::f64::consts::PI;

    /// Pure cosine → analytic signal magnitude ≈ 1 (away from edges).
    #[test]
    fn analytic_signal_cosine_magnitude() {
        let n = 256usize;
        let f0 = 10.0_f64;
        let data: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * f0 * i as f64 / n as f64).cos())
            .collect();
        let z = analytic_signal(&data);
        // Skip 10 samples at each edge where Gibbs artefacts may occur
        for c in &z[10..n - 10] {
            assert_abs_diff_eq!(c.norm(), 1.0, epsilon = 0.02);
        }
    }

    /// Analytic signal of a cosine has imaginary part ≈ -sine (shifted by -π/2).
    #[test]
    fn analytic_signal_imag_is_negative_sine() {
        let n = 256usize;
        let f0 = 8.0_f64;
        let data: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * f0 * i as f64 / n as f64).cos())
            .collect();
        let z = analytic_signal(&data);
        for (i, zi) in z.iter().enumerate().take(n - 10).skip(10) {
            // H{cos(ωt)} = +sin(ωt), so z(t) = cos(ωt) + i·sin(ωt)
            let expected_imag = (2.0 * PI * f0 * i as f64 / n as f64).sin();
            assert_abs_diff_eq!(zi.im, expected_imag, epsilon = 0.02);
        }
    }

    /// STFT column count matches expected number of windows.
    #[test]
    fn stft_window_count() {
        let data = vec![0.0f64; 100];
        let nfft = 16;
        let overlap = 8;
        let step = nfft - overlap; // 8
        let expected_windows = (data.len() - nfft) / step + 1; // (100 - 16) / 8 + 1 = 11
        let result = stft(&data, nfft, overlap);
        assert_eq!(result[0].len(), expected_windows);
    }

    /// STFT freq_bins = nfft/2 + 1.
    #[test]
    fn stft_freq_bins() {
        let data = vec![0.0f64; 64];
        let nfft = 32;
        let result = stft(&data, nfft, 0);
        assert_eq!(result.len(), nfft / 2 + 1);
    }

    /// STFT of a pure sine wave has a peak at the expected frequency bin.
    #[test]
    fn stft_peak_at_correct_bin() {
        let nfft = 64usize;
        let target_bin = 4usize; // frequency = target_bin * (sr / nfft)
        // Generate enough samples for several non-overlapping windows
        let n = nfft * 8;
        let data: Vec<f64> = (0..n)
            .map(|i| (2.0 * PI * target_bin as f64 * i as f64 / nfft as f64).sin())
            .collect();
        let result = stft(&data, nfft, 0);
        // In each window, bin `target_bin` should dominate
        for win in 0..result[0].len() {
            let peak_bin = (0..result.len())
                .max_by(|&a, &b| {
                    result[a][win]
                        .norm()
                        .partial_cmp(&result[b][win].norm())
                        .unwrap()
                })
                .unwrap();
            assert_eq!(peak_bin, target_bin);
        }
    }
}

