await commit(`Fix IFB spectrum overflow and test its bin handling

ifb_music_spectrum multiplied the per-bin spectra before taking the root; with
bins = None at nfft 1024 the product of 512 spectra overflowed to inf on
single-source_300Hz_80deg_1.0s (26 of 720 angles), and the argmax landed on
one of them. Accumulate the geometric mean as a sum of logarithms instead.

Also test that a repeated bin equals the single bin, out-of-range bins are
skipped, and data shorter than one window gives a flat spectrum.`);
await edit('src/stft.rs', `    /// STFT freq_bins = nfft/2 + 1.`, `    #[test]
    #[should_panic(expected = "nfft must be at least 1")]
    fn stft_rejects_zero_nfft() {
        stft(&[0.0; 8], 0, 0);
    }

    #[test]
    #[should_panic(expected = "no_overlap must be less than nfft")]
    fn stft_rejects_overlap_of_whole_window() {
        stft(&[0.0; 8], 4, 4);
    }

    /// With overlap, window w starts at sample w·(nfft − no_overlap): its DC bin is the sum
    /// of exactly those samples.
    #[test]
    fn stft_overlapping_windows_start_at_step() {
        let data: Vec<f64> = (0..20).map(f64::from).collect();
        let (nfft, overlap) = (8, 5);
        let result = stft(&data, nfft, overlap);
        assert_eq!(result[0].len(), 5); // (20 − 8) / 3 + 1
        for (w, dc) in result[0].iter().enumerate() {
            let start = w * (nfft - overlap);
            let expected: f64 = data[start..start + nfft].iter().sum();
            assert_abs_diff_eq!(dc.re, expected, epsilon = 1e-9);
            assert_abs_diff_eq!(dc.im, 0.0, epsilon = 1e-9);
        }
    }

    /// STFT freq_bins = nfft/2 + 1.`);
await $`cargo fmt && cargo clippy --all-targets -- -D warnings`;
const g6 = await $`cargo test --release -- --include-ignored 2>&1 | grep -E "^test result|FAILED|panicked"`.nothrow().text();
g6

