#[test]
fn ifb_music_broadband_high_freqs_120deg() {
    let estimator = MusicEstimator::default();
    let data = load_composite_source(120, &[3600, 4700, 5800], "2.0s");

    let component_freqs = [3600.0_f64, 4700.0, 5800.0];
