#[test]
fn ifb_music_broadband_single_source_all_angles_targeted_bins() {
    let estimator = MusicEstimator::default();
    let freqs: [u32; 3] = [300, 1400, 2500];
    let bins: Vec<usize> = freqs
        .iter()
        .map(|&f| freq_to_bin(f as f64, NFFT, SAMPLE_RATE))
