await edit('CLAUDE.md', `## Workflow
`, `## Workflow

- Before implementing a non-trivial change, propose a plan and get it approved first. While planning, ask clarifying questions about anything ambiguous (scope, API shape, defaults, test data) rather than guessing.
`);
await $`git add CLAUDE.md`;
await commit(`Ask Claude to propose a plan and clarify before implementing`);
({log: await $`git log --oneline -1`.text(), wf: (await file('CLAUDE.md').text()).match(/## Workflow[\s\S]*?\n\n- Make/)[0]})

