1	// Integration tests for musicrs
2	//
3	// Tests DOA estimation against the pre-recorded single-source WAV test data.
4	// Each WAV file is a 4-channel, 24-bit PCM, 16 kHz recording whose filename
5	// encodes the source frequency, true DOA, and duration.
6	
7	mod common;
8	
9	use musicrs::MusicEstimator;
10	
11	/// For every WAV file in `tests/data/single-source/`, estimate the DOA of the
12	/// single source and verify it is within ±5° of the ground-truth angle encoded
13	/// in the filename.
14	#[test]
15	#[ignore = "slow"]
16	fn test_single_source_doa() {
17	    let estimator = MusicEstimator::default();
18	    let tolerance_deg = 5.0_f64;
19	
20	    let mut total = 0usize;
21	    let mut failures: Vec<String> = Vec::new();
22	
23	    for path in common::wav_files() {
24	        let meta = common::parse_meta(&path);
25	        let name = path.file_name().unwrap().to_string_lossy().into_owned();
26	        let (sample_rate, real_data) = common::read_wav_4ch(&path);
27	        assert_eq!(sample_rate as f64, estimator.sample_rate);
28	        total += 1;
29	
30	        let estimated_angles = estimator.estimate_doa_from_real(&real_data, 1, meta.frequency_hz);
31	        let Some(estimate) = estimated_angles.first() else {
32	            failures.push(format!(
33	                "{name}: no peak found (expected {:.1}°)",
34	                meta.doa_deg
35	            ));
36	            continue;
37	        };
38	        let estimated_deg = estimate.to_degrees();
39	
40	        // A linear x-axis array has mirror symmetry: a(θ) = a(360°−θ).
41	        // At exactly Nyquist (f == sr/2), the real steering vector adds two more
42	        // equivalent angles: a(θ) = a(180°−θ) = a(180°+θ).
43	        let nyquist = sample_rate as f64 / 2.0;
44	        let truth = meta.doa_deg;
45	        let equivalent_angles: Vec<f64> = if (meta.frequency_hz - nyquist).abs() < 0.5 {
46	            vec![truth, 360.0 - truth, 180.0 - truth, 180.0 + truth]
47	        } else {
48	            vec![truth, 360.0 - truth]
49	        };
50	        let error = common::angular_error(estimated_deg, &equivalent_angles);
51	
52	        if error > tolerance_deg {
53	            failures.push(format!(
54	                "{name}: expected {truth:.1}° (equivalents: {equivalent_angles:?}), got {estimated_deg:.1}° (error {error:.1}°)"
55	            ));
56	        }
57	    }
58	
59	    if !failures.is_empty() {
60	        panic!(
61	            "{}/{} files failed DOA accuracy test (tolerance ±{:.0}°):\n{}",
62	            failures.len(),
63	            total,
64	            tolerance_deg,
65	            failures.join("\n")
66	        );
67	    }
68	
69	    println!("All {total} single-source DOA tests passed (tolerance ±{tolerance_deg:.0}°).");
70	}

