1	// IFB-MUSIC on the single-source WAV data, using the one STFT bin that holds the tone.
2	//
3	// nfft = 160 at 16 kHz gives 100 Hz bins, so every test tone falls exactly on a bin.
4	// Tones at or above Nyquist are excluded: at Nyquist the DOA is ambiguous
5	// (θ, 180° ± θ), and above it the STFT only sees the aliased frequency.
6	
7	mod common;
8	
9	use musicrs::MusicEstimator;
10	
11	const NFFT: usize = 160;
12	
13	#[test]
14	fn ifb_single_bin_doa() {
15	    let est = MusicEstimator::default();
16	    let tolerance_deg = 5.0_f64;
17	    let nyquist = est.sample_rate / 2.0;
18	
19	    let mut total = 0usize;
20	    let mut failures = Vec::new();
21	
22	    for path in common::wav_files() {
23	        let meta = common::parse_meta(&path);
24	        if meta.frequency_hz >= nyquist {
25	            continue;
26	        }
27	        let (sample_rate, data) = common::read_wav_4ch(&path);
28	        assert_eq!(sample_rate as f64, est.sample_rate);
29	        let bin = (meta.frequency_hz * NFFT as f64 / est.sample_rate).round() as usize;
30	
31	        let (spectrum, angles) = est.ifb_music_spectrum(&data, NFFT, 1, Some(&[bin]));
32	        let argmax = (0..spectrum.len())
33	            .max_by(|&a, &b| spectrum[a].total_cmp(&spectrum[b]))
34	            .unwrap();
35	        let estimated_deg = angles[argmax].to_degrees();
36	        let error = common::angular_error(estimated_deg, &[meta.doa_deg, 360.0 - meta.doa_deg]);
37	        total += 1;
38	        if error > tolerance_deg {
39	            failures.push(format!(
40	                "{}: expected {:.1}°, got {estimated_deg:.1}° (error {error:.1}°)",
41	                path.file_name().unwrap().to_string_lossy(),
42	                meta.doa_deg
43	            ));
44	        }
45	    }
46	
47	    assert!(total > 0, "no test files below Nyquist");
48	    assert!(
49	        failures.is_empty(),
50	        "{}/{total} files failed IFB DOA test (tolerance ±{tolerance_deg:.0}°):\n{}",
51	        failures.len(),
52	        failures.join("\n")
53	    );
54	    println!("All {total} IFB single-bin DOA tests passed (tolerance ±{tolerance_deg:.0}°).");
55	}

