mod common;
use musicrs::{MusicEstimator, select_bins_by_energy};
#[test]
fn probe() {
    let est = MusicEstimator::default();
    for nfft in [160usize, 1024] { for th in [10.0, 20.0, 30.0] {
        let mut worst = (0.0f64, String::new()); let mut maxbins = 0; let mut none_worst = 0.0f64;
        for path in common::wav_files() {
            let meta = common::parse_meta(&path);
            if meta.frequency_hz >= 8000.0 { continue; }
            let (_, data) = common::read_wav_4ch(&path);
            let bins = select_bins_by_energy(&data, nfft, th);
            maxbins = maxbins.max(bins.len());
            let (s, a) = est.ifb_music_spectrum(&data, nfft, 1, Some(&bins));
            let am = (0..s.len()).max_by(|&x, &y| s[x].total_cmp(&s[y])).unwrap();
            let e = common::angular_error(a[am].to_degrees(), &[meta.doa_deg, 360.0 - meta.doa_deg]);
            if e > worst.0 { worst = (e, format!("{:?} bins {:?}", path.file_name().unwrap(), bins)); }
            if th == 20.0 {
                let (s, a) = est.ifb_music_spectrum(&data, nfft, 1, None);
                let am = (0..s.len()).max_by(|&x, &y| s[x].total_cmp(&s[y])).unwrap();
                none_worst = none_worst.max(common::angular_error(a[am].to_degrees(), &[meta.doa_deg, 360.0 - meta.doa_deg]));
            }
        }
        println!("PROBE nfft {nfft} th {th}: worst {:.2} ({}) maxbins {maxbins} none_worst {none_worst:.1}", worst.0, worst.1);
    }}
}

