await write('tests/zz_probe_test.rs', `mod common;
use musicrs::{MusicEstimator, select_bins_by_energy};
fn err(est: &MusicEstimator, data: &nalgebra::DMatrix<f64>, nfft: usize, bins: &[usize], doa: f64) -> f64 {
    let (s, a) = est.ifb_music_spectrum(data, nfft, 1, Some(bins));
    let am = (0..s.len()).max_by(|&x, &y| s[x].total_cmp(&s[y])).unwrap();
    common::angular_error(a[am].to_degrees(), &[doa, 360.0 - doa])
}
#[test]
fn probe() {
    let est = MusicEstimator::default();
    let nfft = 1024;
    for th in [1.0, 3.0, 6.0, 10.0] {
        let (mut worst, mut worst_nonendfire, mut over) = (0.0f64, 0.0f64, 0);
        for path in common::wav_files() {
            let meta = common::parse_meta(&path);
            if meta.frequency_hz >= 8000.0 { continue; }
            let (_, data) = common::read_wav_4ch(&path);
            let e = err(&est, &data, nfft, &select_bins_by_energy(&data, nfft, th), meta.doa_deg);
            worst = worst.max(e); if meta.doa_deg != 0.0 { worst_nonendfire = worst_nonendfire.max(e); } if e > 0.5 { over += 1; }
        }
        println!("PROBE single nfft {nfft} th {th}: worst {worst:.2} non-endfire {worst_nonendfire:.2} over0.5 {over}/70");
    }
    for th in [6.0, 10.0, 20.0] {
        let mut worst = 0.0f64; let mut nb = 0;
        for freqs in [[300u32, 1400, 2500], [3600, 4700, 5800], [1400, 4700, 6900]] { for doa in [0u32, 40, 80, 120, 160] { for (n, dur) in [(160usize, "2.0s"), (1024, "2.0s")] {
            let parts: Vec<_> = freqs.iter().map(|&f| common::read_wav_4ch(&common::wav_path(f, doa, dur)).1).collect();
            let len = parts.iter().map(|p| p.ncols()).min().unwrap();
            let data = parts.iter().fold(nalgebra::DMatrix::zeros(4, len), |acc, p| acc + p.columns(0, len));
            let bins = select_bins_by_energy(&data, n, th); nb = nb.max(bins.len());
            let e = err(&est, &data, n, &bins, doa as f64);
            if e > worst { worst = e; println!("  th {th} {freqs:?} {doa} nfft {n}: {e:.2} bins {bins:?}"); }
        }}}
        println!("PROBE composite th {th}: worst {worst:.2} maxbins {nb}");
    }
}`);
const pr2b = await $`cargo test --release --test zz_probe_test -- --nocapture 2>&1 | grep -E "PROBE|  th|error|panicked" | head -40`.nothrow().text();
