    let high_band: [u32; 2] = [6900, 8000];
    let mut log = common::ErrorLog::new("IFB frequency triples");

    for fl in low_band {
        for fm in mid_band {
            for fh in high_band {
                let triple = [fl, fm, fh];
                let bins: Vec<usize> = triple
                    .iter()
                    .map(|&f| freq_to_bin(f as f64, NFFT, SAMPLE_RATE))
                    .collect();
