  $`git -C ${WT} log --oneline origin/feat/test-gaps..HEAD`.text(),
  $`git -C ${WT} diff --stat origin/feat/test-gaps..HEAD -- . ':!tests/golden/*.csv'`.text(),
  $`cargo test --release -- --include-ignored 2>&1 | grep -E "^test result|FAILED|panicked"`.cwd(WT).nothrow().text(),
