]);
const csvCount = await $`git -C ${WT} diff --name-only origin/feat/test-gaps..HEAD -- 'tests/golden/*.csv' | wc -l`.text();
({wlog, wstat, csvCount, wtest, mainStatus, ign, branch: await $`git -C ${WT} branch --show-current`.text()})

